newblock=r'''function cloneStreamDict(pdf,ref){const d=pdf.newDictionary(),s=deepObj(ref);s.forEach((v,k)=>{k=String(k);if(k!=='Length'&&k!=='Filter'&&k!=='DecodeParms')d.put(k,v)});return d}
function addCloneStream(pdf,ref,text){return pdf.addStream(raw(text),cloneStreamDict(pdf,ref))}
function uniqueXName(res,prefix='BlueIso'){const xd=deepObj(deepObj(res)?.get?.('XObject'));if(!xd?.isDictionary?.())throw new Error('la instancia no tiene diccionario XObject editable');for(let n=1;n<10000;n++){const k=prefix+n;if(!xd.get(k))return{k,xd}}throw new Error('no encontré un nombre libre para el XObject aislado')}
function invocationShape(s){return(s?.invocations||[]).map(x=>String(x.name||'')).join('>')}
function isolateInstanceStroke(pdf,page,target){if(!target?.invocations?.length)throw new Error('el trazo no está dentro de una instancia Form/XObject aislable');const leafText=latin(target.sourceRef.readStream());if(target.start<0||target.end>leafText.length||target.start>=target.end)throw new Error('rango inválido del trazo dentro del Form');let clone=addCloneStream(pdf,target.sourceRef,leafText.slice(0,target.start)+leafText.slice(target.end));const roots=new Set(refs(page).map(deepKey));for(let z=target.invocations.length-1;z>=0;z--){const inv=target.invocations[z];if(!inv.parentRef||!inv.res||inv.nameStart<0||inv.nameEnd<=inv.nameStart)throw new Error('la cadena de instancia no conserva un Do editable');const {k,xd}=uniqueXName(inv.res);xd.put(k,clone);const txt=latin(inv.parentRef.readStream());if(inv.nameEnd>txt.length)throw new Error('el Do de la instancia quedó fuera de rango');const mod=txt.slice(0,inv.nameStart)+'/'+k+txt.slice(inv.nameEnd);if(roots.has(deepKey(inv.parentRef))){inv.parentRef.writeStream(raw(mod));return true}clone=addCloneStream(pdf,inv.parentRef,mod)}throw new Error('la cadena de instancia no llegó a un stream raíz de página')}
async function buildLargeInstancePlan(){
 const baseRoute=routes[0]?.slice();if(!baseRoute||baseRoute.length!==selectedVisual)throw new Error('no existe una ruta base completa para reparación por instancia');
 let cw=null,cp=null;try{
  cw=mupdf.PDFDocument.openDocument(outBase,'application/pdf');cp=cw.loadPage(0);const base=collectVisual(cp),baseSigs=base.map(sig),cm=deepModel(cp);
  if(base.length!==beforeVisual||!cm||cm.incomplete||cm.strokes.length!==beforeStruct)throw new Error('la copia de reparación no reproduce el modelo base');
  const baseBag=new Map();for(const k of baseSigs)baseBag.set(k,(baseBag.get(k)||0)+1);const need=new Map(),blueVisualBySig=new Map();for(const oi of selectedOrdinals){const k=baseSigs[oi];need.set(k,(need.get(k)||0)+1);(blueVisualBySig.get(k)||blueVisualBySig.set(k,[]).get(k)).push(base[oi])}
  function diff(av){const ab=new Map();for(const v of av){const k=sig(v);ab.set(k,(ab.get(k)||0)+1)}const removed=new Map(),added=new Map();for(const[k,n]of baseBag){const d=Math.max(0,n-(ab.get(k)||0));if(d)removed.set(k,d)}for(const[k,n]of ab){const d=Math.max(0,n-(baseBag.get(k)||0));if(d)added.set(k,d)}return{removed,added}}
  async function routeDiff(indices){const groups=new Map();for(const idx of indices){const t=cm.strokes[idx];if(!t||t.editable===false)throw new Error('la ruta base contiene un operador no editable');const key=deepKey(t.sourceRef);let g=groups.get(key);if(!g){g={ref:t.sourceRef,original:latin(t.sourceRef.readStream()),ranges:[]};groups.set(key,g)}g.ranges.push([t.start,t.end])}try{for(const g of groups.values()){let text=g.original;for(const[a,b]of g.ranges.sort((A,B)=>B[0]-A[0]))text=text.slice(0,a)+text.slice(b);g.ref.writeStream(raw(text))}try{cp?.destroy?.()}catch(_){}cp=cw.loadPage(0);return diff(collectVisual(cp))}finally{for(const g of groups.values())g.ref.writeStream(raw(g.original));try{cp?.destroy?.()}catch(_){}cp=cw.loadPage(0)}}
  async function single(idx){const t=cm.strokes[idx];if(!t||t.editable===false)return null;const orig=latin(t.sourceRef.readStream());try{t.sourceRef.writeStream(raw(orig.slice(0,t.start)+orig.slice(t.end)));try{cp?.destroy?.()}catch(_){}cp=cw.loadPage(0);const d=diff(collectVisual(cp));let total=0,key=null;for(const[k,n]of d.removed){total+=n;if(n===1)key=k}return total===1&&d.added.size===0?key:null}finally{t.sourceRef.writeStream(raw(orig));try{cp?.destroy?.()}catch(_){}cp=cw.loadPage(0)}}
  status.textContent='Aislando exactamente lo azul…';const d=await routeDiff(baseRoute),missing=new Map(),extra=new Map();for(const[k,n]of need){const got=d.removed.get(k)||0;if(got<n)missing.set(k,n-got)}for(const[k,n]of d.removed){const bn=need.get(k)||0;if(n>bn)extra.set(k,n-bn)}const missCount=[...missing.values()].reduce((a,b)=>a+b,0),extraCount=[...extra.values()].reduce((a,b)=>a+b,0),addedCount=[...d.added.values()].reduce((a,b)=>a+b,0);causalDiagnostic='aislamiento de instancia · ruta='+selectedVisual+' · faltantes='+missCount+' · no azules='+extraCount+' · nuevas='+addedCount;if(missCount!==1||extraCount!==1||addedCount!==0)throw new Error('la desviación no es una sustitución 1↔1 aislable · '+causalDiagnostic);
  const missingSig=[...missing.keys()][0],extraSig=[...extra.keys()][0],missingV=(blueVisualBySig.get(missingSig)||[])[0],extraV=base.find(v=>sig(v)===extraSig);if(!missingV||!extraV)throw new Error('no pude recuperar la pareja visual 1↔1');
  const offenderRank=baseRoute.map(idx=>({idx,c:alignCost(extraV,cm.strokes[idx])})).filter(x=>Number.isFinite(x.c)).sort((a,b)=>a.c-b.c);let offender=-1,offTests=0;for(const r of offenderRank){const k=await single(r.idx);offTests++;if(k===extraSig){offender=r.idx;break}if(offTests%20===0)status.textContent='Aislando azul · localizando la única pareja incorrecta…'}if(offender<0)throw new Error('no se localizó el operador que borra el trazo no azul');
  const ranked=[];for(let idx=0;idx<cm.strokes.length;idx++){if(baseRoute.includes(idx))continue;const st=cm.strokes[idx];if(!st||st.editable===false||!st.invocations?.length)continue;const c=alignCost(missingV,st);if(Number.isFinite(c))ranked.push({idx,c})}ranked.sort((a,b)=>a.c-b.c);let replacement=-1,fingerprint=null,tests=0,max=Math.min(220,ranked.length);
  for(let q=0;q<max;q++){const idx=ranked[q].idx;let td=null,tp=null;try{td=mupdf.PDFDocument.openDocument(outBase,'application/pdf');tp=td.loadPage(0);const bv=collectVisual(tp),bm=deepModel(tp),bb=new Map();for(const v of bv){const k=sig(v);bb.set(k,(bb.get(k)||0)+1)}const st=bm.strokes[idx];if(!st?.invocations?.length)continue;isolateInstanceStroke(td,tp,st);tp.destroy?.();tp=td.loadPage(0);const av=collectVisual(tp),ab=new Map();for(const v of av){const k=sig(v);ab.set(k,(ab.get(k)||0)+1)}let removed=[],added=0;for(const[k,n]of bb){const x=Math.max(0,n-(ab.get(k)||0));for(let j=0;j<x;j++)removed.push(k)}for(const[k,n]of ab)added+=Math.max(0,n-(bb.get(k)||0));tests++;if(removed.length===1&&removed[0]===missingSig&&added===0){replacement=idx;fingerprint={sourceBase:st.sourceBase,shape:invocationShape(st),bbox:[...st.bbox],lines:st.lines,curves:st.curves,segs:st.segs,width:st.width,rgb:[...(st.rgb||[])]};break}}catch(_){}finally{try{tp?.destroy?.()}catch(_){}try{td?.destroy?.()}catch(_){}}if(tests%10===0)status.textContent='Aislando azul · probando instancia correcta '+tests+'/'+max+'…'}
  if(replacement<0)throw new Error('no encontré una instancia Form/XObject aislable que produzca exactamente el azul faltante · pruebas='+tests);
  causalDiagnostic+=' · operador incorrecto='+offender+' · instancia aislable encontrada en '+tests+' prueba(s) · COPY-ON-WRITE';return{kind:'instance',baseRoute,offender,replacement,fingerprint,missingSig};
 }finally{try{cp?.destroy?.()}catch(_){}try{cw?.destroy?.()}catch(_){}}
}
async function buildCausalRoute(){return selectedVisual>600?buildLargeInstancePlan():buildCausalRouteSmall()}
async function attemptInstance(plan,number,saveMode){let work=null,wp=null,check=null,cp=null;try{work=mupdf.PDFDocument.openDocument(outBase,'application/pdf');wp=work.loadPage(0);const baseline=collectVisual(wp),baseSigs=baseline.map(sig),wm=deepModel(wp);if(baseline.length!==beforeVisual||!wm||wm.incomplete||wm.strokes.length!==beforeStruct)throw new Error('la copia de instancia no reproduce el modelo base');const selectedSet=new Set(selectedOrdinals),expectedFinal=new Map();for(let i=0;i<baseline.length;i++){if(selectedSet.has(i))continue;const k=baseSigs[i];expectedFinal.set(k,(expectedFinal.get(k)||0)+1)}const bagEq=(a,exp,len)=>{if(a.length!==len)return false;const b=new Map();for(const v of a){const k=sig(v);b.set(k,(b.get(k)||0)+1)}if(b.size!==exp.size)return false;for(const[k,n]of exp)if(b.get(k)!==n)return false;return true};const regular=plan.baseRoute.filter(i=>i!==plan.offender),targets=regular.map(i=>wm.strokes[i]);if(targets.some(x=>!x||x.editable===false))throw new Error('la ruta de 825 contiene un operador no editable');const edits=new Map();for(const t of targets){const k=deepKey(t.sourceRef)+'|'+t.start+'|'+t.end;if(!edits.has(k))edits.set(k,{ref:t.sourceRef,key:deepKey(t.sourceRef),start:t.start,end:t.end})}const groups=new Map();for(const e of edits.values())(groups.get(e.key)||groups.set(e.key,{ref:e.ref,ranges:[]}).get(e.key)).ranges.push([e.start,e.end]);for(const g of groups.values()){let text=latin(g.ref.readStream());for(const[a,b]of g.ranges.sort((A,B)=>B[0]-A[0]))text=text.slice(0,a)+text.slice(b);g.ref.writeStream(raw(text))}wp.destroy?.();wp=work.loadPage(0);const intermediate=collectVisual(wp),expInter=new Map(expectedFinal);expInter.set(plan.missingSig,(expInter.get(plan.missingSig)||0)+1);if(!bagEq(intermediate,expInter,beforeVisual-selectedVisual+1))throw new Error('la ruta base menos la pareja incorrecta no deja exactamente original menos 825 azules');const wm2=deepModel(wp),candidates=[];const missOrdinal=selectedOrdinals.find(i=>sig(classicVisual[i])===plan.missingSig),targetV=classicVisual[missOrdinal];for(const st of wm2.strokes){if(!st?.invocations?.length||st.sourceBase!==plan.fingerprint.sourceBase||invocationShape(st)!==plan.fingerprint.shape)continue;const c=alignCost(targetV,st);if(Number.isFinite(c))candidates.push({st,c})}candidates.sort((a,b)=>a.c-b.c);if(!candidates.length)throw new Error('después de borrar los demás azules no pude reencontrar la instancia aislable');isolateInstanceStroke(work,wp,candidates[0].st);wp.destroy?.();wp=work.loadPage(0);const preview=collectVisual(wp);if(!bagEq(preview,expectedFinal,beforeVisual-selectedVisual))throw new Error('la cirugía por instancia no produjo exactamente original menos azul');const previewRaster=await rasterDigest(wp);if(saveMode==='incremental'&&work.canBeSavedIncrementally?.()===false)throw new Error('MuPDF indica que este PDF no admite guardado incremental');const outBuf=work.saveToBuffer(saveMode),out=new Uint8Array(U(outBuf));wp.destroy?.();wp=null;work.destroy();work=null;check=mupdf.PDFDocument.openDocument(out,'application/pdf');cp=check.loadPage(0);if(await rasterDigest(cp)!==previewRaster)throw new Error('después de guardar, el renderizado cambió respecto de la versión exacta validada');return{out,touched:groups.size+1,number,saveMode:saveMode||'reescritura mínima'}}finally{try{cp?.destroy?.()}catch(_){}try{check?.destroy?.()}catch(_){}try{wp?.destroy?.()}catch(_){}try{work?.destroy?.()}catch(_){}}}
'''
